        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def get_neighbors(r, c):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    visited_start = set()
    visited_goal = set()
    start_queue = deque([(start, [start])])
    goal_queue = deque([(goal, [goal])])
    visited_start.add(start)
    visited_goal.add(goal)

    while start_queue and goal_queue:
        # Expand from start
        if len(start_queue) <= len(goal_queue):
            r1, path1 = start_queue.popleft()
            for r2, path2 in goal_queue:
                if r1 == r2:
                    return path1 + path2[::-1][1:]
            for nr, nc in get_neighbors(r1[0], r1[1]):
