from collections import deque

def solve(grid, start, goal):
    if not grid or start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(queue, visited, other_visited, reverse):
        while queue:
            current = queue.popleft()
            if current in other_visited:
                path = []
                path.append(current)
                node = current
                while node in visited:
                    node = visited[node]
                    path.append(node)
                path.reverse()
                return path
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in visited:
                    visited[(r, c)] = current
                    queue.append((r, c))
        return []

    start_queue = deque([start])
    goal_queue = deque([goal])
    start_visited = {start: None}
    goal_visited = {goal: None}

    while start_queue and goal_queue:
        path1 = bfs(start_queue, start_visited, goal_visited, False)
        if path1:
            return path1
        path2 = bfs(goal_queue, goal_visited, start_visited, True)
        if path2:
            return path2

    return []
