def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list for the original graph
    def build_graph():
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
        return graph

    # Build adjacency list for the reversed graph
    def build_reversed_graph():
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[v].append((u, w))
        return graph

    # Dijkstra's algorithm
    def dijkstra(graph, start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        visited = set()

        while heap:
            current_dist, u = heapq.heappop(heap)
            if u in visited:
                continue
            visited.add(u)
            if u == end:
                return current_dist
            for v, w in graph[u]:
                if dist[v] > current_dist + w:
                    dist[v] = current_dist + w
                    heapq.heappush(heap, (dist[v], v))
