def solve(n, edges, s, t):
    if s == t:
        return 0

    from collections import defaultdict

    # Build adjacency list
    adj = defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bucket queue: a list of buckets, each bucket is a list of nodes at that distance
    # We use a dictionary to map distance to list of nodes
    buckets = defaultdict(list)

    # Initialize the bucket queue
    # Start with distance 0
    buckets[0].append(s)
    dist = {node: float('inf') for node in range(n)}
    dist[s] = 0

    while buckets:
        # Find the smallest distance bucket that is not empty
        for d in sorted(buckets.keys()):
            if buckets[d]:
                break
        else:
            break  # No more nodes to process

        # Process all nodes in the current bucket
        for node in buckets[d]:
            # Remove node from the bucket
            buckets[d].remove(node)

            # If node is the target, return the distance
            if node == t:
                return d

            # Traverse all neighbors
            for neighbor, weight in adj[node]:
                if dist[neighbor] > d + weight:
                    dist[neighbor] = d + weight
                    # Move the neighbor to the new distance bucket
                    if buckets[d + weight]:
                        # If the bucket already has nodes, we just append
                        pass
                    else:
                        # Create new bucket if needed
                        buckets[d + weight] = []
                    buckets[d + weight].append(neighbor)

    # If target is not reachable
    return -1
